stopifnot({x<-rawToChar(as.raw(c(201,223))); Encoding(x)<-"latin1"; y<-tolower(x); identical(y,"\u00e9\u00df") && identical(Encoding(y),"UTF-8")})
stopifnot({x<-rawToChar(as.raw(c(97,233)));Encoding(x)<-"bytes";identical(tryCatch(toupper(x),error=function(e)conditionMessage(e)), 'translating strings with "bytes" encoding is not allowed')})
stopifnot({x<-rawToChar(as.raw(c(97,233)));Encoding(x)<-"bytes";identical(tryCatch(tolower(x),error=function(e)conditionMessage(e)), 'translating strings with "bytes" encoding is not allowed')})
stopifnot({x<-rawToChar(as.raw(c(97,255)));Encoding(x)<-"UTF-8";e<-tryCatch(toupper(x),error=function(e)conditionMessage(e));grepl("^invalid input",e,useBytes=TRUE) && grepl("in 'utf8towcs'$",e,useBytes=TRUE)})
