stopifnot({x<-rawToChar(as.raw(128:159));Encoding(x)<-"latin1";identical(tolower(x),"\u20ac<81>\u201a\u0192\u201e\u2026\u2020\u2021\u02c6\u2030\u0161\u2039\u0153<8d>\u017e<8f><90>\u2018\u2019\u201c\u201d\u2022\u2013\u2014\u02dc\u2122\u0161\u203a\u0153<9d>\u017e\u00ff")})
